/* HEXA BATTLEGROUNDS setup — PART 83 OF 83. Run parts in order. Safe to re-run. */ create or replace function _auto_roles(p_arena uuid) returns boolean language plpgsql as $$ declare v_any boolean; t record; r text; v_p uuid; begin v_any := _auto_roles_v8(p_arena); for t in select tm.id from teams tm where tm.arena_id = p_arena and tm.ready and not exists (select 1 from players q where q.team_id = tm.id and q.active and q.role is null) and (select count(*) from players q where q.team_id = tm.id and q.active and not q.away) between 1 and 3 loop for r in select x from unnest(array['scout', 'decoder', 'intel', 'captain']) x where not exists (select 1 from players q where q.team_id = t.id and q.active and (q.role = x or q.role2 = x)) loop continue when r = 'captain'; select id into v_p from players where team_id = t.id and active and not away and role2 is null order by (role = 'captain'), random() limit 1; exit when v_p is null; update players set role2 = r, role2_bot = (select count(*) from players q where q.team_id = t.id and q.active) < 3 where id = v_p; insert into squad_chat(team_id, name, kind, body) select t.id, 'Hexa Air', 'system', display_name || ' also covers the ' || r || ' role' from players where id = v_p; perform _ping_team(t.id, 'roles'); v_any := true; end loop; end loop; return v_any; end $$; create or replace function host_online_start(p_token text, p_length text default 'standard') returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_seal jsonb; v_squads int; v_maps int; v_size int; v_max int; i int; v_arena uuid; t record; k int := 0; v_ids uuid[]; v_res jsonb := '[]'::jsonb; a record; v_bus int; begin v_ev := _auth_host(p_token); if _cfg(v_ev, 'online') <> 1 then raise exception 'NOT_ONLINE_EVENT'; end if; if _cfg(v_ev, 'online_started') = 1 then raise exception 'ALREADY_STARTED'; end if; if coalesce(p_length, 'standard') not in ('quick', 'standard', 'full') then raise exception 'BAD_LENGTH'; end if; perform pg_advisory_xact_lock(hashtext('online:' || v_ev::text)); v_seal := _online_seal_event(v_ev); delete from teams tm where tm.event_id = v_ev and not exists (select 1 from players q where q.team_id = tm.id and q.active); select count(*) into v_squads from teams where event_id = v_ev and ready; if v_squads = 0 then raise exception 'NO_READY_SQUADS'; end if; v_size := least(15, greatest(1, _cfg(v_ev, 'arena_size'))); v_max := _cfg(v_ev, 'online_max_maps'); v_maps := least(greatest(1, ceil(v_squads::numeric / v_size)::int), v_max); if v_squads > v_maps * v_size then raise exception 'TOO_MANY_SQUADS: % squads need more than % maps — raise "Most maps"', v_squads, v_max; end if; for i in 1..v_maps loop if not exists (select 1 from arenas where event_id = v_ev and number = i) then insert into arenas(event_id, number, name) values (v_ev, i, 'Map ' || i); end if; end loop; select array_agg(id order by number) into v_ids from arenas where event_id = v_ev and number <= v_maps; for t in select id from teams where event_id = v_ev and ready order by random() loop update teams set arena_id = v_ids[1 + (k % v_maps)] where id = t.id; k := k + 1; end loop; update teams set arena_id = v_ids[1] where event_id = v_ev and not ready; for a in select id from arenas where event_id = v_ev and number <= v_maps loop v_bus := 0; for t in select id from teams where arena_id = a.id order by number loop update teams set bus = 1 + v_bus / greatest(1, _cfg(v_ev, 'bus_size')) where id = t.id; v_bus := v_bus + 1; end loop; end loop; update events set settings = settings || '{"online_started": 1}'::jsonb where id = v_ev; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'online_start', jsonb_build_object('squads', v_squads, 'maps', v_maps, 'length', p_length) || v_seal); for i in 1..v_maps loop v_res := v_res || jsonb_build_object('map', i, 'start', host_command(p_token, v_ids[i], 'start_match', jsonb_build_object('length', coalesce(p_length, 'standard')), 'online start')); end loop; return jsonb_build_object('squads', v_squads, 'maps', v_maps, 'merged', v_seal -> 'moved', 'left_out', v_seal -> 'left_out', 'started', v_res); end $$; drop function if exists _player_state_v10(text); alter function player_state(text) rename to _player_state_v10; create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; begin v := _player_state_v10(p_token); if jsonb_typeof(v -> 'online') = 'object' then v := jsonb_set(v, '{online,started}', to_jsonb(_cfg((select event_id from players p join teams t on t.id = p.team_id where p.session_hash = _hash(p_token)), 'online_started') = 1)); end if; return v; end $$; create or replace function host_online_summary(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_sq int; v_size int; begin v_ev := _auth_host(p_token); select count(*) into v_sq from teams t where t.event_id = v_ev and exists (select 1 from players q where q.team_id = t.id and q.active); v_size := least(15, greatest(1, _cfg(v_ev, 'arena_size'))); return jsonb_build_object( 'players', (select count(*) from online_members where event_id = v_ev), 'started', _cfg(v_ev, 'online_started') = 1, 'max_maps', _cfg(v_ev, 'online_max_maps'), 'squads', v_sq, 'full', (select count(*) from teams t where t.event_id = v_ev and (select count(*) from players q where q.team_id = t.id and q.active) = 4), 'three', (select count(*) from teams t where t.event_id = v_ev and (select count(*) from players q where q.team_id = t.id and q.active) = 3), 'short', (select count(*) from teams t where t.event_id = v_ev and (select count(*) from players q where q.team_id = t.id and q.active) between 1 and 2), 'maps_needed', greatest(1, ceil(greatest(v_sq, 1)::numeric / v_size)::int), 'maps', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'number', a.number, 'phase', a.phase, 'squads', (select count(*) from teams t where t.arena_id = a.id), 'ready', (select count(*) from teams t where t.arena_id = a.id and t.ready), 'full', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) = 4), 'short', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) between 1 and 2), 'players', (select count(*) from players q join teams t on t.id = q.team_id where t.arena_id = a.id and q.active)) order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev)); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary', 'host_online_start']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
